/**
 * Returns the unique city+category intro paragraph, or null if not defined.
 * @param {string} city  — lowercase city slug, e.g. "bangalore"
 * @param {string} catValue — category slug, e.g. "birthday-photography"
 * @returns {string|null}
 */
export function getCityCategoryIntro(city, catValue) {
  if (!city || !catValue) return null;
  return CITY_CATEGORY_INTROS[city.toLowerCase()]?.[catValue] || null;
}
